/**
 * Dumps the live catalogue into a seed fixture, so `git clone && npm run
 * db:seed` gives a stranger the same 52 products.
 *
 * Deliberately omitted: `_id` (Mongo assigns fresh ones), `slug` (the model's
 * pre-validate hook regenerates it from the title, so the fixture cannot drift
 * out of sync with the slug rules), and `embedding` (a 384-number array per
 * product would bloat the repo, and it is regenerated by the embed script).
 *
 * `createdAt` is kept, because a fresh clone whose 52 products all share one
 * timestamp makes "sort by newest" look broken in the demo.
 */
import { writeFile } from "node:fs/promises";
import mongoose from "mongoose";
import connectDB from "../lib/db/connect.js";
import Product from "../modules/product/product.model.js";

await connectDB();

const products = await Product.find({})
  .sort({ createdAt: 1 })
  .select("title description price category image stock isActive createdAt")
  .lean();

const fixture = products.map(({ _id, ...fields }) => fields);

const target = new URL("./seed-data.json", import.meta.url);
await writeFile(target, `${JSON.stringify(fixture, null, 2)}\n`, "utf8");

console.log(`exported ${fixture.length} products -> scripts/seed-data.json`);

await mongoose.disconnect();
